sys_script_client.script:
function onLoad() {
	if ( g_form.getValue('state') != 1){
		return;
	}
	if (g_form.getValue('form_type') == 0){
		g_form.setValue('requestor',g_user.userID);
		return;
	}
    //Checking logged in User assignment group and based on the keyword in group, it will assign the site and country
    var userGroupMap = new Map([
        ['CN', {
            country: 'China',
            site: 'CN'
        }],
        ['AU', {
            country: 'Australia',
            site: 'AU'
        }],
        ['ID', {
            country: 'Indonesia',
            site: 'ID'
        }],
        ['TH', {
            country: 'Thailand',
            site: 'TH'
        }],
        ['BN', {
            country: 'Brunei',
            site: 'BN'
        }],
        ['LK', {
            country: 'Sri Lanka',
            site: 'LK'
        }],
        ['BD', {
            country: 'Bangladesh',
            site: 'BD'
        }],
        ['HK', {
            country: 'Hong Kong',
            site: 'HK'
        }],
        ['IN', {
            country: 'India',
            site: 'IN'
        }],
        ['JP', {
            country: 'Japan',
            site: 'JP'
        }],
        ['MU', {
            country: 'Mauritius',
            site: 'MU'
        }],
        ['MO', {
            country: 'Macao',
            site: 'MO'
        }],
        ['PH', {
            country: 'Philippines',
            site: 'PH'
        }],
        ['MY', {
            country: 'Malaysia',
            site: 'MY'
        }],
        ['BS', {
            country: 'Bahamas',
            site: 'BS'
        }],
        ['NZ', {
            country: 'New Zealand',
            site: 'NZ'
        }],
        ['KR', {
            country: 'Korea',
            site: 'KR'
        }],
        ['SG', {
            country: 'Singapore',
            site: 'SG'
        }],
        ['TW', {
            country: 'Taiwan',
            site: 'TW'
        }],
        ['VN', {
            country: 'Vietnam',
            site: 'VN'
        }],
        ['CA', {
            country: 'Canada',
            site: 'CA'
        }],
        ['BR', {
            country: 'Brazil',
            site: 'BR'
        }]
    ]);

    var userSysId = g_user.userID;
    var userGroups = new GlideRecord('sys_user_grmember');
    userGroups.addQuery('user', userSysId);
    userGroups.query(cb);
    // Assume one user one site
    function cb(item) {
        while (userGroups.next()) {
            var adGroup = userGroups.getDisplayValue('group');
			var adGroupSysID = userGroups.getValue('group');
            if (adGroup.includes('-SSI-HBAP-')) {
                var user_site = adGroup.split('-').pop();
                var user_country = userGroupMap.get(user_site);

                g_form.setValue('ssi_site', user_site + "-" + user_country.country);
				g_form.setValue('assignment_group', adGroupSysID);
				//g_form.setValue('signatory',userSysId);
				g_form.setValue('requestor',userSysId);
               // g_form.setValue('country_territory', user_country.country); //incorrect

				break;
            }
        }
    }



}
